import React, { useEffect, useState } from 'react';

function App() {
  const [scores, setScores] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;

    const fetchData = () => {
      fetch('http://localhost:5000/api/score')
        .then(res => res.json())
        .then(data => {
          if (isMounted) {
            setScores(data);
            setLoading(false);
          }
        })
        .catch(() => {
          if (isMounted) setLoading(false);
        });
    };

    fetchData(); // 최초 호출
    const interval = setInterval(fetchData, 3000); // 3초마다 폴링

    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  return (
    <div style={{ padding: 24 }}>
      <h1>점수판</h1>
      {loading ? (
        <p>로딩 중...</p>
      ) : (
        <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', minWidth: 320 }}>
          <thead>
            <tr>
              {scores.length > 0 ? (
                Object.keys(scores[0]).map((key) => (
                  <th key={key}>{key}</th>
                ))
              ) : (
                <th>점수 데이터 없음</th>
              )}
            </tr>
          </thead>
          <tbody>
            {scores.length === 0 ? (
              <tr>
                <td colSpan="100%">점수가 없습니다.</td>
              </tr>
            ) : (
              scores.map((score, idx) => (
                <tr key={idx}>
                  {Object.values(score).map((val, i) => (
                    <td key={i}>{val}</td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default App;
